import{_ as l,a0 as t,w as d,s as o,ao as r,I as p,x as a,a1 as e,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"掌握 Linux 用户組 | LCTT x X-CMD","titleTemplate":false,"description":"掌握 Linux 用户組 | LCTT (201907) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"掌握 Linux 用户組 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"掌握 Linux 用户組 | LCTT (201907) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201907/20190717 Mastering user groups on Linux","title":"掌握 Linux 用户組","tag":"201907","desc":""},"relativePath":"201907/20190717 Mastering user groups on Linux.md","filePath":"[post].md"}'),c={name:"201907/20190717 Mastering user groups on Linux.md"};function h(g,s,u,b,k,f){const n=t("Link");return d(),o("div",null,[s[15]||(s[15]=r(`<h1 id="掌握-linux-用户組" tabindex="-1">掌握 Linux 用户組 <a class="header-anchor" href="#掌握-linux-用户組" aria-label="Permalink to “掌握 Linux 用户組”">​</a></h1><blockquote><p>在 Linux 系統中管理用户組並不費力，但相關命令可能比你所知的更為靈活。</p></blockquote><p><img src="https://images.idgesg.net/images/article/2019/07/carrots-100801917-large.jpg" alt="Scott 97006 CC BY 2.0"></p><p>在 Linux 系統中用户組起着重要作用。用户組提供了一種簡單方法供一組用户互相共享文件。用户組也允許系統管理員更加有效地管理用户權限，因為管理員可以將權限分配給用户組而不是逐一分配給單個用户。</p><p>儘管通常只要在系統中添加用户賬户就會創建用户組，關於用户組如何工作以及如何運用用户組還有很多需要了解的。</p><h3 id="一個用户一個用户組" tabindex="-1">一個用户一個用户組？ <a class="header-anchor" href="#一個用户一個用户組" aria-label="Permalink to “一個用户一個用户組？”">​</a></h3><p>Linux 系統中多數用户賬户被設為用户名與用户組名相同。用户 <code>jdoe</code> 會被賦予一個名為 <code>jdoe</code> 的用户組，且成為該新建用户組的唯一成員。如本例所示，該用户的登錄名，用户 id 和用户組 id 在新建賬户時會被添加到 <code>/etc/passwd</code> 和 <code>/etc/group</code> 文件中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo useradd jdoe</span></span>
<span class="line"><span>$ grep jdoe /etc/passwd</span></span>
<span class="line"><span>jdoe:x:1066:1066:Jane Doe:/home/jdoe:/bin/sh</span></span>
<span class="line"><span>$ grep jdoe /etc/group</span></span>
<span class="line"><span>jdoe:x:1066:</span></span></code></pre></div><p>這些文件中的配置使系統得以在文本（<code>jdoe</code>）和數字（<code>1066</code>）這兩種用户 id 形式之間互相轉換—— <code>jdoe</code> 就是 <code>1006</code>，且 <code>1006</code> 就是 <code>jdoe</code>。</p><p>分配給每個用户的 UID（用户 id）和 GID（用户組 id）通常是一樣的，並且順序遞增。若上例中 Jane Doe 是最近添加的用户，分配給下一個新用户的用户 id 和用户組 id 很可能都是 1067。</p><h3 id="gid-uid" tabindex="-1">GID = UID？ <a class="header-anchor" href="#gid-uid" aria-label="Permalink to “GID = UID？”">​</a></h3><p>UID 和 GID 可能不一致。例如，如果你用 <code>groupadd</code> 命令添加一個用户組而不指定用户組 id，系統會分配下一個可用的用户組 id（在本例中為 1067）。下一個添加到系統中的用户其 UID 會是 1067 而 GID 則為 1068。</p><p>你可以避免這個問題，方法是添加用户組的時候指定一個較小的用户組 id 而不是接受默認值。在下面的命令中我們添加一個用户組並提供一個 GID，這個 GID 小於用於用户賬户的 GID 取值範圍。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo groupadd -g 500 devops</span></span></code></pre></div><p>創建賬户時你可以指定一個共享用户組，如果這樣對你更合適的話。例如你可能想把新來的開發人員加入同一個 DevOps 用户組而不是一人一個用户組。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo useradd -g staff bennyg</span></span>
<span class="line"><span>$ grep bennyg /etc/passwd</span></span>
<span class="line"><span>bennyg:x:1064:50::/home/bennyg:/bin/sh</span></span></code></pre></div><h3 id="主要用户組和次要用户組" tabindex="-1">主要用户組和次要用户組 <a class="header-anchor" href="#主要用户組和次要用户組" aria-label="Permalink to “主要用户組和次要用户組”">​</a></h3><p>用户組實際上有兩種：<ruby>主要用户組<rt>primary group</rt></ruby>和<ruby>次要用户組<rt>secondary group</rt></ruby>。</p><p>主要用户組是保存在 <code>/etc/passwd</code> 文件中的用户組，該用户組在賬户創建時配置。當用户創建一個文件時，用户的主要用户組與此文件關聯。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ whoami</span></span>
<span class="line"><span>jdoe</span></span>
<span class="line"><span>$ grep jdoe /etc/passwd</span></span>
<span class="line"><span>jdoe:x:1066:1066:John Doe:/home/jdoe:/bin/bash</span></span>
<span class="line"><span>             ^</span></span>
<span class="line"><span>             |</span></span>
<span class="line"><span>             +-------- 主要用户組</span></span>
<span class="line"><span>$ touch newfile</span></span>
<span class="line"><span>$ ls -l newfile</span></span>
<span class="line"><span>-rw-rw-r-- 1 jdoe jdoe 0 Jul 16 15:22 newfile</span></span>
<span class="line"><span>                   ^</span></span>
<span class="line"><span>                   |</span></span>
<span class="line"><span>                   +-------- 主要用户組</span></span></code></pre></div><p>用户一旦擁有賬户之後被加入的那些用户組是次要用户組。次要用户組成員關係在 <code>/etc/group</code> 文件中顯示。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ grep devops /etc/group</span></span>
<span class="line"><span>devops:x:500:shs,jadep</span></span>
<span class="line"><span>          ^</span></span>
<span class="line"><span>          |</span></span>
<span class="line"><span>          +-------- shs 和 jadep 的次要用户組</span></span></code></pre></div><p><code>/etc/group</code> 文件給用户組分配組名稱（例如 <code>500</code> = <code>devops</code>）並記錄次要用户組成員。</p><h3 id="首選的準則" tabindex="-1">首選的準則 <a class="header-anchor" href="#首選的準則" aria-label="Permalink to “首選的準則”">​</a></h3><p>每個用户是他自己的主要用户組成員，並可以成為任意多個次要用户組成員，這樣的一種準則允許用户更加容易地將個人文件和需要與同事分享的文件分開。當用户創建一個文件時，用户所屬的不同用户組的成員不一定有訪問權限。用户必須用 <code>chgrp</code> 命令將文件和次要用户組關聯起來。</p><h3 id="哪裏也不如自己的家目錄" tabindex="-1">哪裏也不如自己的家目錄 <a class="header-anchor" href="#哪裏也不如自己的家目錄" aria-label="Permalink to “哪裏也不如自己的家目錄”">​</a></h3><p>添加新賬户時一個重要的細節是 <code>useradd</code> 命令並不一定為新用户添加一個<ruby>家目錄<rt>/home</rt></ruby>家目錄。若你只有某些時候想為用户添加家目錄，你可以在 <code>useradd</code> 命令中加入 <code>-m</code> 選項（可以把它想像成“安家”選項）。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo useradd -m -g devops -c &quot;John Doe&quot; jdoe2</span></span></code></pre></div><p>此命令中的選項如下：</p><ul><li><code>-m</code> 創建家目錄並在其中生成初始文件</li><li><code>-g</code> 指定用户歸屬的用户組</li><li><code>-c</code> 添加賬户描述信息（通常是用户的姓名）</li></ul><p>若你希望總是創建家目錄，你可以編輯 <code>/etc/login.defs</code> 文件來更改默認工作方式。更改或添加 <code>CREATE_HOME</code> 變量並將其設置為 <code>yes</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ grep CREATE_HOME /etc/login.defs</span></span>
<span class="line"><span>CREATE_HOME     yes</span></span></code></pre></div><p>另一種方法是用自己的賬户設置別名從而讓 <code>useradd</code> 一直帶有 <code>-m</code> 選項。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ alias useradd=’useradd -m’</span></span></code></pre></div><p>確保將該別名添加到你的 <code>~/.bashrc</code> 文件或類似的啓動文件中以使其永久生效。</p><h3 id="深入瞭解-etc-login-defs" tabindex="-1">深入瞭解 /etc/login.defs <a class="header-anchor" href="#深入瞭解-etc-login-defs" aria-label="Permalink to “深入瞭解 /etc/login.defs”">​</a></h3><p>下面這個命令可列出 <code>/etc/login.defs</code> 文件中的全部設置。下面的 <code>grep</code> 命令會隱藏所有註釋和空行。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat /etc/login.defs | grep -v &quot;^#&quot; | grep -v &quot;^$&quot;</span></span>
<span class="line"><span>MAIL_DIR        /var/mail</span></span>
<span class="line"><span>FAILLOG_ENAB            yes</span></span>
<span class="line"><span>LOG_UNKFAIL_ENAB        no</span></span>
<span class="line"><span>LOG_OK_LOGINS           no</span></span>
<span class="line"><span>SYSLOG_SU_ENAB          yes</span></span>
<span class="line"><span>SYSLOG_SG_ENAB          yes</span></span>
<span class="line"><span>FTMP_FILE       /var/log/btmp</span></span>
<span class="line"><span>SU_NAME         su</span></span>
<span class="line"><span>HUSHLOGIN_FILE  .hushlogin</span></span>
<span class="line"><span>ENV_SUPATH      PATH=/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin</span></span>
<span class="line"><span>ENV_PATH        PATH=/usr/local/bin:/usr/bin:/bin:/usr/local/games:/usr/games</span></span>
<span class="line"><span>TTYGROUP        tty</span></span>
<span class="line"><span>TTYPERM         0600</span></span>
<span class="line"><span>ERASECHAR       0177</span></span>
<span class="line"><span>KILLCHAR        025</span></span>
<span class="line"><span>UMASK           022</span></span>
<span class="line"><span>PASS_MAX_DAYS   99999</span></span>
<span class="line"><span>PASS_MIN_DAYS   0</span></span>
<span class="line"><span>PASS_WARN_AGE   7</span></span>
<span class="line"><span>UID_MIN                  1000</span></span>
<span class="line"><span>UID_MAX                 60000</span></span>
<span class="line"><span>GID_MIN                  1000</span></span>
<span class="line"><span>GID_MAX                 60000</span></span>
<span class="line"><span>LOGIN_RETRIES           5</span></span>
<span class="line"><span>LOGIN_TIMEOUT           60</span></span>
<span class="line"><span>CHFN_RESTRICT           rwh</span></span>
<span class="line"><span>DEFAULT_HOME    yes</span></span>
<span class="line"><span>CREATE_HOME         yes                 &lt;===</span></span>
<span class="line"><span>USERGROUPS_ENAB yes</span></span>
<span class="line"><span>ENCRYPT_METHOD SHA512</span></span></code></pre></div><p>注意此文件中的各種設置會決定用户 id 的取值範圍以及密碼使用期限和其他設置（如 umask）。</p><h3 id="如何顯示用户所屬的用户組" tabindex="-1">如何顯示用户所屬的用户組 <a class="header-anchor" href="#如何顯示用户所屬的用户組" aria-label="Permalink to “如何顯示用户所屬的用户組”">​</a></h3><p>出於各種原因用户可能是多個用户組的成員。用户組成員身份給與用户對用户組擁有的文件和目錄的訪問權限，有時候這種工作方式是至關重要的。要生成某個用户所屬用户組的清單，用 <code>groups</code> 命令即可。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ groups jdoe</span></span>
<span class="line"><span>jdoe : jdoe adm admin cdrom sudo dip plugdev lpadmin staff sambashare</span></span></code></pre></div><p>你可以鍵入不帶任何參數的 <code>groups</code> 命令來列出你自己的用户組。</p><h3 id="如何添加用户至用户組" tabindex="-1">如何添加用户至用户組 <a class="header-anchor" href="#如何添加用户至用户組" aria-label="Permalink to “如何添加用户至用户組”">​</a></h3><p>如果你想添加一個已有用户至別的用户組，你可以仿照下面的命令操作：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo usermod -a -G devops jdoe</span></span></code></pre></div><p>你也可以指定逗號分隔的用户組列表來添加一個用户至多個用户組：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo usermod -a -G devops,mgrs jdoe</span></span></code></pre></div><p>參數 <code>-a</code> 意思是“添加”，<code>-G</code> 指定用户組列表。</p><p>你可以編輯 <code>/etc/group</code> 文件將用户名從用户組成員名單中刪除，從而將用户從用户組中移除。<code>usermod</code> 命令或許也有個選項用於從用户組中刪除某個成員。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>fish:x:16:nemo,dory,shark</span></span>
<span class="line"><span>           |</span></span>
<span class="line"><span>           V</span></span>
<span class="line"><span>fish:x:16:nemo,dory</span></span></code></pre></div><h3 id="提要" tabindex="-1">提要 <a class="header-anchor" href="#提要" aria-label="Permalink to “提要”">​</a></h3><p>添加和管理用户組並非特別困難，但長遠來看配置賬户時的一致性可使這項工作更容易些。</p><hr>`,54)),p("p",null,[s[1]||(s[1]=a("via: ",-1)),e(n,{href:"https://www.networkworld.com/article/3409781/mastering-user-groups-on-linux.html"},{default:i(()=>[...s[0]||(s[0]=[a("https://www.networkworld.com/article/3409781/mastering-user-groups-on-linux.html",-1)])]),_:1})]),p("p",null,[s[6]||(s[6]=a("作者：",-1)),e(n,{href:"https://www.networkworld.com/author/Sandra-Henry_Stocker/"},{default:i(()=>[...s[2]||(s[2]=[a("Sandra Henry-Stocker",-1)])]),_:1}),s[7]||(s[7]=a(" 選題：",-1)),e(n,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[3]||(s[3]=[a("lujun9972",-1)])]),_:1}),s[8]||(s[8]=a(" 譯者：",-1)),e(n,{href:"https://github.com/0x996"},{default:i(()=>[...s[4]||(s[4]=[a("0x996",-1)])]),_:1}),s[9]||(s[9]=a(" 校對：",-1)),e(n,{href:"https://github.com/wxy"},{default:i(()=>[...s[5]||(s[5]=[a("wxy",-1)])]),_:1})]),p("p",null,[s[12]||(s[12]=a("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[10]||(s[10]=[a("LCTT",-1)])]),_:1}),s[13]||(s[13]=a(" 原創編譯，",-1)),e(n,{href:"https://linux.cn/"},{default:i(()=>[...s[11]||(s[11]=[a("Linux中國",-1)])]),_:1}),s[14]||(s[14]=a(" 榮譽推出",-1))])])}const C=l(c,[["render",h]]);export{x as __pageData,C as default};
